#define I2C_BAUD_RATE_50KHZ      50000
#define I2C_BAUD_RATE_100KHZ     100000
#define I2C_BAUD_RATE_200KHZ     200000
#define I2C_BAUD_RATE_400KHZ     400000
#define I2C_DEFAULT_BAUD_RATE    I2C_BAUD_RATE_100KHZ

typedef uint8_t i2c_unit_t; /**< i2c uint id */

typedef enum {
	I2C_ID_0 = 0, /**< i2c id 0 */
#if (SOC_I2C_UNIT_NUM > 1)
	I2C_ID_1,     /**< i2c id 1 */
#endif
#if (SOC_I2C_UNIT_NUM > 2)
	I2C_ID_2,     /**< i2c id 2 */
#endif
	I2C_ID_MAX    /**< i2c id max */
} i2c_id_t;

typedef enum {
	I2C_ADDR_MODE_7BIT = 0, /**< i2c address mode 7bit */
	I2C_ADDR_MODE_10BIT,    /**< i2c address mode 10bit */
} i2c_addr_mode_t;

/*****************************************************************************
 *
 * General Purpose I2C Bus reference driver - Unified Implementation
 * Supports both I2C0 (SIM_I2C0_*) and I2C1 (SIM_I2C1_*) configurations
 * This unified implementation replaces the previous sim_i2c_driver.c and
 * sim_i2c_driver_v2.c files, providing a single codebase that handles both
 * CONFIG_SIM_I2C_HW_BOARD_V3 and non-V3 configurations.
 *
 * To use this file, you must implement the first 9 functions below according
 * To the specific platform IO implementation.
 * To increase the speed, it is recommended to change the functions
 * To inline functions or to macros.
 *****************************************************************************/

#include <driver/gpio.h>
#include <driver/int.h>
#include <driver/i2c.h>
#include "clock_driver.h"
#include "gpio_driver.h"
#include "icu_driver.h"
